import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { writeFile } from 'node:fs/promises';
const desktop = createRequire(new URL('../../apps/desktop/package.json',import.meta.url));
if (!process.versions.electron) {
 const r = spawnSync(desktop('electron'), [fileURLToPath(import.meta.url)], {stdio:'inherit',env:{...process.env,ELECTRON_RUN_AS_NODE:'1'}});
 process.exit(r.status ?? 1);
}
const infra = createRequire(new URL('../../packages/infrastructure/package.json',import.meta.url));
const Database = infra('better-sqlite3');
const {createServer} = await import('vite');
const server = await createServer({configFile:false,logLevel:'silent',server:{middlewareMode:true,hmr:false,ws:false}});
try {
 const c = await server.ssrLoadModule('/packages/infrastructure/src/migrations.ts');
 const a = await server.ssrLoadModule('/.runtime/c-integration/a01c-migrations.ts');
 const tables = db => db.prepare("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name").all().map(x=>x.name);
 const version = db => db.pragma('user_version',{simple:true});
 const cases=[];
 for (const direction of ['A6_to_C7','C6_to_A6','C7_to_A6','C7_to_C7']) {
  const db = new Database(':memory:');
  try {
   if (direction.startsWith('A')) a.migrate(db); else c.migrate(db,direction.startsWith('C6')?c.migrations.slice(0,6):c.migrations);
   const before={version:version(db),tables:tables(db)};
   let outcome='returned_success',errorCode=null;
   try { if(direction.endsWith('A6'))a.migrate(db);else c.migrate(db); } catch(e){outcome='rejected';errorCode=e.code ?? e.message;}
   const after={version:version(db),tables:tables(db)};
   const expected = direction==='A6_to_C7'? outcome==='rejected' && after.version===6 && !after.tables.includes('agent_run') && JSON.stringify(before)===JSON.stringify(after)
    :direction==='C6_to_A6'?outcome==='returned_success' && after.version===6 && !after.tables.includes('knowledge_wiki') && after.tables.includes('agent_write_call')
    :direction==='C7_to_A6'?outcome==='rejected' && errorCode==='DATABASE_NEWER_THAN_APPLICATION' && JSON.stringify(before)===JSON.stringify(after)
    :outcome==='returned_success' && JSON.stringify(before)===JSON.stringify(after);
   cases.push({direction,outcome,errorCode,before,after,expectationConfirmed:expected});
  } finally {db.close();}
 }
 const report={status:cases.every(x=>x.expectationConfirmed)?'passed':'failed',scope:'Synthetic in-memory compatibility diagnostic, not approval to integrate A01c or a claim of compatibility',cases};
 await writeFile('wiki-project/raw/c-integration-migration-probe.json',JSON.stringify(report,null,2)+'\n');
 console.log(JSON.stringify({status:report.status,cases:cases.map(({direction,outcome,errorCode,expectationConfirmed})=>({direction,outcome,errorCode,expectationConfirmed}))}));
 if(report.status!=='passed')process.exitCode=1;
} finally {await server.close();}
